svg.script:
// ═══════════════════════════════════════════════════════════════
// 1:1 port of StatusPanelRenderer.cs — Pure SVG DOM, no canvas
// Embed: <object data="propulsion-animation.svg" type="image/svg+xml">
// ═══════════════════════════════════════════════════════════════

var S = 3;
var AREA = { x: 0, y: 0, w: 200, h: 400 };
var svgNS = 'http://www.w3.org/2000/svg';
var svg = document.documentElement;

// ── Element pools ──
var RPOOL = 550, TPOOL = 25;
var rPool = [], tPool = [];
var rIdx = 0, tIdx = 0;
var prevRIdx = 0, prevTIdx = 0;

for (var i = 0; i < RPOOL; i++) {
  var r = document.createElementNS(svgNS, 'rect');
  r.style.display = 'none';
  svg.appendChild(r);
  rPool.push(r);
}
for (var i = 0; i < TPOOL; i++) {
  var t = document.createElementNS(svgNS, 'text');
  t.setAttribute('font-family', 'monospace');
  t.setAttribute('dominant-baseline', 'hanging');
  t.style.display = 'none';
  svg.appendChild(t);
  tPool.push(t);
}

// ── MFDTheme colors (exact from UIController.cs) ──
var T = {
  BG:[5,8,5], PANEL_BG:[8,14,8], BORDER:[24,40,24], BORDER_LIGHT:[20,30,20],
  DIM_TEXT:[42,74,42], DIM_TEXT_MID:[58,90,58], MID_TEXT:[74,122,74],
  ACCENT:[64,160,64], BAR_TRACK:[6,10,6], BAR_FILL:[48,144,48],
  STATUS_VAL:[80,144,80], WARN:[192,160,48]
};
var C_ENG_BODY = [20,35,20], C_ENG_LINE = [40,70,40];
var PHI = 1.6180339887, TWO_PI = Math.PI * 2;

// ── State ──
var tick = 0, thrControl = 0, abActive = false, abActiveTicks = 0, lastAbState = false;
var smoothedVel = 60, smoothedYawDrift = 0, smoothedPitchDrift = 0;
var phase = 0, phaseTick = 0;

// ── Drawing primitives ──
function rgb(c) { return 'rgb(' + c[0] + ',' + c[1] + ',' + c[2] + ')'; }

function Rect(cx, cy, w, h, color, alpha) {
  if (rIdx >= RPOOL) return;
  var el = rPool[rIdx++];
  el.setAttribute('x', (cx - w/2) * S);
  el.setAttribute('y', (cy - h/2) * S);
  el.setAttribute('width', w * S);
  el.setAttribute('height', h * S);
  el.setAttribute('fill', rgb(color));
  el.setAttribute('opacity', (alpha !== undefined ? alpha : 255) / 255);
  el.style.display = '';
}

function RectRGBA(cx, cy, w, h, r, g, b, a) {
  if (rIdx >= RPOOL) return;
  var el = rPool[rIdx++];
  el.setAttribute('x', (cx - w/2) * S);
  el.setAttribute('y', (cy - h/2) * S);
  el.setAttribute('width', w * S);
  el.setAttribute('height', h * S);
  el.setAttribute('fill', 'rgb(' + r + ',' + g + ',' + b + ')');
  el.setAttribute('opacity', a / 255);
  el.style.display = '';
}

function DrawRectangleOutline(x, y, w, h, thickness, color) {
  Rect(x + w/2, y + thickness/2, w, thickness, color);
  Rect(x + w/2, y + h - thickness/2, w, thickness, color);
  Rect(x + thickness/2, y + h/2, thickness, h, color);
  Rect(x + w - thickness/2, y + h/2, thickness, h, color);
}

function Txt(text, x, y, scale, color, align) {
  if (tIdx >= TPOOL) return;
  var el = tPool[tIdx++];
  var fontSize = scale * 28 * S;
  el.setAttribute('x', x * S);
  el.setAttribute('y', y * S);
  el.setAttribute('font-size', fontSize);
  el.setAttribute('fill', rgb(color));
  el.setAttribute('text-anchor', align === 'center' ? 'middle' : align === 'right' ? 'end' : 'start');
  el.textContent = text;
  el.style.display = '';
}

function lerp(a, b, t) { return a + (b - a) * t; }
function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

// ═══════════════════════════════════════════════════════════════
// DrawTurbineDisc — exact port of StatusPanelRenderer.cs:148-201
// ═══════════════════════════════════════════════════════════════
function DrawTurbineDisc(schX, cy, radius, numBlades, rotAngle, bladeChord,
                         bladeR, bladeG, bladeB, bladeA,
                         hubR, hubG, hubB, damaged) {
  if (damaged) return;
  var hubRad = radius * 0.18;

  // Back blades (sinA < 0)
  for (var b = 0; b < numBlades; b++) {
    var bAngle = rotAngle + b / numBlades * TWO_PI;
    var cosA = Math.cos(bAngle);
    var sinA = Math.sin(bAngle);
    if (sinA >= 0) continue;
    var tipX = cosA * radius;
    var hubTipX = cosA * hubRad;
    var apparentH = 0.8 + Math.abs(sinA) * bladeChord * 1.5;
    var depthAlpha = 0.3 + (sinA + 1) * 0.35;
    var alpha = Math.floor(bladeA * depthAlpha);
    var bladeLen = Math.abs(tipX - hubTipX);
    var bladeCX = schX + (tipX + hubTipX) / 2;
    if (bladeLen > 0.3)
      RectRGBA(bladeCX, cy, bladeLen, apparentH,
        Math.max(0, bladeR - 15), Math.max(0, bladeG - 15), Math.max(0, bladeB - 10), alpha);
  }

  // Hub
  RectRGBA(schX, cy, hubRad * 1.6, hubRad * 1.6, hubR, hubG, hubB, 140);
  RectRGBA(schX, cy, hubRad * 0.6, hubRad * 0.6,
    Math.min(255, hubR + 20), Math.min(255, hubG + 20), Math.min(255, hubB + 15), 100);

  // Front blades (sinA >= 0)
  for (var b = 0; b < numBlades; b++) {
    var bAngle = rotAngle + b / numBlades * TWO_PI;
    var cosA = Math.cos(bAngle);
    var sinA = Math.sin(bAngle);
    if (sinA < 0) continue;
    var tipX = cosA * radius;
    var hubTipX = cosA * hubRad;
    var apparentH = 0.8 + Math.abs(sinA) * bladeChord * 1.5;
    var depthAlpha = 0.3 + (sinA + 1) * 0.35;
    var alpha = Math.floor(bladeA * depthAlpha);
    var bladeLen = Math.abs(tipX - hubTipX);
    var bladeCX = schX + (tipX + hubTipX) / 2;
    if (bladeLen > 0.3)
      RectRGBA(bladeCX, cy, bladeLen, apparentH, bladeR, bladeG, bladeB, alpha);
  }
}

// ═══════════════════════════════════════════════════════════════
// DrawEngineCol — exact port of StatusPanelRenderer.cs:203-532
// ═══════════════════════════════════════════════════════════════
function DrawEngineCol(x, y, w, availH, label, thr, ab, tk, velocity) {
  var fn = 3, tot = 3, maxKN = 300;
  var curKN = maxKN * Math.min(thr / 0.8, 1.0);
  var abMax = ab ? 200 : 0, abCur = ab ? 200 : 0;
  var totalMax = maxKN + (ab ? 200 : 0), totalCur = curKN + abCur;
  var thrustPct = totalMax > 0 ? totalCur / totalMax : 0;
  var hpC = fn >= tot ? T.ACCENT : T.WARN;

  Txt(label, x, y, 0.35, T.MID_TEXT, 'left');
  Txt(fn + '/' + tot, x + w, y, 0.32, hpC, 'right');

  var schTop = y + 13, schH = (availH - 30) * 0.75;
  if (schH < 10) schH = 10;
  var schW = 18, schX = x + w / 2;
  var seed = label === "ENG L" ? 0 : 1.7;

  // Intake funnel
  var intakeH = schH * 0.08, intakeW = schW * 1.3;
  Rect(schX, schTop + intakeH / 2, intakeW, intakeH, C_ENG_BODY);
  Rect(schX, schTop, intakeW, 0.5, C_ENG_LINE);

  // Compressor body
  var bodyTop = schTop + intakeH, bodyH = schH * 0.45;
  Rect(schX, bodyTop + bodyH / 2, schW, bodyH, C_ENG_BODY);
  var segs = Math.max(Math.min(tot, 5), 2), segH = bodyH / segs;
  for (var s = 1; s < segs; s++)
    Rect(schX, bodyTop + s * segH, schW - 2, 0.5, C_ENG_LINE);

  for (var s = 0; s < segs; s++) {
    if (Math.floor(s * tot / segs) >= fn && Math.floor(tk / 10) % 2 === 0)
      RectRGBA(schX, bodyTop + s * segH + segH / 2, schW - 2, segH - 1, 60, 20, 15, 255);
  }
  DrawRectangleOutline(schX - schW / 2, bodyTop, schW, bodyH, 0.5, C_ENG_LINE);

  // Combustion chamber
  var combTop = bodyTop + bodyH, combH = schH * 0.15, combW = schW + 2;
  var glowR = Math.floor(20 + (55 - 20) * thrustPct);
  var glowG = Math.floor(35 + (40 - 35) * thrustPct);
  var glowB = Math.max(0, Math.floor(20 + (15 - 20) * thrustPct));
  RectRGBA(schX, combTop + combH / 2, combW, combH, glowR, glowG, glowB, 255);
  DrawRectangleOutline(schX - combW / 2, combTop, combW, combH, 0.5, C_ENG_LINE);

  // Central shaft
  var shaftTop = schTop + intakeH * 0.3, shaftBot = combTop + combH * 0.9;
  RectRGBA(schX, (shaftTop + shaftBot) / 2, 1.5, shaftBot - shaftTop, 35, 55, 35, 100);
  RectRGBA(schX, (shaftTop + shaftBot) / 2, 0.5, shaftBot - shaftTop, 55, 80, 55, 70);

  // 3D Compressor blade discs
  var spinSpeed = 0.04 + thrustPct * 0.22, stageRadius = (schW - 4) / 2;
  for (var s = 0; s < segs; s++) {
    var dmg = Math.floor(s * tot / segs) >= fn;
    var stageCY = bodyTop + s * segH + segH / 2;
    var numBlades = 12 + s * 4;
    var direction = (s % 2 === 0) ? 1 : -1;
    var chord = 2.5 - s * 0.3;
    var rot = tk * spinSpeed * direction + s * 0.9 + seed;
    DrawTurbineDisc(schX, stageCY, stageRadius, numBlades, rot, chord,
      70, 120, 70, 180, 45, 75, 45, dmg);
  }

  // 3D Turbine discs in combustion chamber
  var turbRadius = (combW - 4) / 2, turbSpinSpeed = spinSpeed * 0.7;
  for (var ts = 0; ts < 2; ts++) {
    var turbCY = combTop + combH * (0.3 + ts * 0.4);
    var heat = 1 - ts * 0.3;
    var hR = Math.floor(80 + thrustPct * 70 * heat);
    var hG = Math.floor(65 + thrustPct * 30 * heat);
    var dir = (ts % 2 === 0) ? 1 : -1;
    var rot2 = tk * turbSpinSpeed * dir + ts * 1.5 + seed + 3;
    DrawTurbineDisc(schX, turbCY, turbRadius, 8, rot2, 2.0,
      hR, hG, 40, 160, Math.max(0, hR - 20), Math.max(0, hG - 15), 30, false);
  }

  // Nozzle
  var nozzTop = combTop + combH, nozzH = schH * 0.12;
  var nozzWTop = schW, nozzWBot = schW * 0.5;
  for (var i = 0; i < 3; i++) {
    var nt = i / 3;
    RectRGBA(schX, nozzTop + nozzH * nt + nozzH / 6, lerp(nozzWTop, nozzWBot, nt), nozzH / 3, 15, 22, 15, 255);
  }

  // Air particles
  var velFactor = clamp(velocity / 100.0, 0, 1);
  var flowBotY = combTop + combH, approachTopY = schTop - 20;
  var flowTotalH = flowBotY - approachTopY;
  var pSpeed = Math.max(0.003, 0.003 + thrustPct * 0.018);

  for (var p = 0; p < 48; p++) {
    var rawPhase = (tk * pSpeed + p * PHI) % 1;
    var warpedPhase = rawPhase * rawPhase * (3 - 2 * rawPhase);
    var py = approachTopY + warpedPhase * flowTotalH;
    var px, pDepth;

    if (py < schTop) {
      var approachT = clamp((schTop - py) / 20, 0, 1);
      var laneAngle = p * PHI * 3.7;
      var lane = Math.sin(laneAngle) * 0.9;
      var entryOffset = Math.cos(laneAngle * 1.3 + 0.7) * 0.4;
      var farX = schX + (lane + entryOffset) * schW * 1.8 * 0.5;
      var nearX = schX + lane * intakeW * 0.35;
      px = lerp(nearX, farX, approachT * approachT);
      pDepth = 0.5;
    } else {
      var relY = py - bodyTop;
      var stageIdx = Math.floor(relY / segH);
      var inC = (relY >= 0 && stageIdx < segs);
      var spiralAngle;
      if (inC) {
        var d2 = (stageIdx % 2 === 0) ? 1 : -1;
        spiralAngle = tk * spinSpeed * (1 + stageIdx * 0.25) * d2 + stageIdx * 0.9 + seed + p * (TWO_PI / 48);
      } else {
        spiralAngle = tk * spinSpeed * 1.5 + p * 1.3 + warpedPhase * 5;
      }
      var maxR = (schW - 3) / 2;
      var depthProgress = clamp((py - bodyTop) / (flowBotY - bodyTop), 0, 1);
      var spiralR = maxR * (0.6 + Math.sin(p * 2.7 + tk * 0.05) * 0.2) * (1 - depthProgress * 0.6);
      px = schX + Math.cos(spiralAngle) * spiralR + smoothedYawDrift * depthProgress * 0.6;
      pDepth = Math.sin(spiralAngle);
    }

    var insideEng = py >= bodyTop;
    var stageDepth = insideEng ? clamp((py - bodyTop) / (flowBotY - bodyTop), 0, 1) : 0;
    var compressionSize = 1 + stageDepth * 0.8;
    var pW = (1.0 + (pDepth + 1) * 0.4 + (p % 2) * 0.3) * compressionSize;
    var pH2 = (1.2 + velFactor) * compressionSize;

    var edgeFade;
    if (warpedPhase < 0.1) edgeFade = warpedPhase / 0.1;
    else if (warpedPhase > 0.85) edgeFade = (1 - warpedPhase) / 0.15;
    else edgeFade = 1;
    var pAlpha = Math.floor((0.2 + thrustPct * 0.8) * 130 * edgeFade * (0.5 + (pDepth + 1) * 0.25));

    if (pAlpha > 4) {
      var hp = Math.max(0, (warpedPhase - 0.15) / 0.85);
      RectRGBA(px, py, pW, pH2, Math.floor(55 + hp * 45), Math.floor(130 + (p % 3) * 15 - hp * 25), Math.floor(55 + hp * 15), pAlpha);
    }
  }

  // Exhaust plume
  var exhaTop = nozzTop + nozzH, maxPlumeH = schH * 0.3, nozzExitW = nozzWBot * 0.8;
  var flameStage = 0;
  if (ab && abCur > 0.1) flameStage = 2;
  else if (thrustPct > 0.70) flameStage = 1;

  if (thrustPct > 0.01) {
    var driftX = smoothedYawDrift, driftY = smoothedPitchDrift;
    var basePlumeH = maxPlumeH * thrustPct * (1 + velFactor * 0.25);
    if (flameStage === 2) basePlumeH *= 1.3;
    var tongues = thrustPct > 0.5 ? 3 : 2;
    var slices = flameStage === 2 ? 10 : (thrustPct > 0.4 ? 12 : 8);

    // Outer glow
    for (var sl = 0; sl < 6; sl++) {
      var gt = sl / 5;
      var gs1 = Math.sin(tk * 0.23 + sl * 1.7 + seed);
      var gY = exhaTop + basePlumeH * gt * 0.8 + 1 + driftY * gt * gt;
      var gX = schX + driftX * gt * gt + gs1 * 0.5;
      var gW = nozzExitW * (1.2 - gt * 0.8) + gs1 * 0.5;
      gW *= 1 - velFactor * 0.15 * gt;
      var gA = Math.floor(30 * (1 - gt * gt));
      if (gA < 3) continue;
      if (flameStage === 2)
        RectRGBA(gX, gY, gW, basePlumeH / 5, Math.floor(lerp(120,60,gt)), Math.floor(lerp(70,30,gt)), 10, gA);
      else
        RectRGBA(gX, gY, gW, basePlumeH / 5, 20, Math.floor(lerp(50,25,gt)), Math.floor(lerp(90,40,gt)), gA);
    }

    // Flame tongues
    for (var tongue = 0; tongue < tongues; tongue++) {
      var tseed = seed + tongue * 2.17;
      var tongueBaseX = 0;
      if (tongues === 3) tongueBaseX = (tongue - 1) * nozzExitW * 0.2;
      else if (tongues === 2) tongueBaseX = (tongue - 0.5) * nozzExitW * 0.15;
      var tongueLenMul = tongue === Math.floor(tongues / 2) ? 1 : 0.75 + Math.sin(tk * 0.13 + tseed) * 0.1;

      for (var sl = 0; sl < slices; sl++) {
        var t = sl / (slices - 1);
        var s1 = Math.sin(tk * 0.41 + sl * 0.9 + tseed);
        var s2 = Math.sin(tk * 0.67 + sl * 1.3 + tseed * 1.4);
        var s3 = Math.sin(tk * 0.23 + sl * 2.1 + tseed * 0.7);

        var tw = nozzExitW * 0.35 * (1 - t * 0.85);
        tw *= 1 - velFactor * 0.2 * t;
        tw += tw * s2 * 0.15;
        tw = Math.max(tw, 0.3);

        var slH2 = basePlumeH * tongueLenMul / slices * 1.3;
        slH2 += slH2 * s1 * 0.08;
        slH2 = Math.max(slH2, 0.3);

        var wobbleDamp = 1 - velFactor * 0.5;
        var wx = tongueBaseX + s3 * tw * 0.4 * wobbleDamp + s1 * 1.2 * wobbleDamp;
        wx += driftX * t * t;
        var slY = exhaTop + basePlumeH * tongueLenMul * t * 0.85 + slH2 * 0.3;
        slY += s1 * 1.5 + driftY * t * t;
        var slX = schX + wx;

        var cR, cG, cB, cA;
        switch (flameStage) {
          case 2:
            cR = Math.floor(lerp(255,140,t)); cG = Math.floor(lerp(220,50,t));
            cB = Math.floor(lerp(130,10,t)); cA = Math.floor(lerp(200,30,t*t));
            if (t < 0.2) { cR = Math.min(255, cR + Math.floor(s2*20)); cG = Math.min(255, cG + Math.floor(s2*15)); }
            break;
          case 1:
            if (t < 0.12) { cR = Math.floor(lerp(210,140,t/0.12)); cG = Math.floor(lerp(235,190,t/0.12)); cB = 255; cA = 210; }
            else if (t < 0.45) { var mt = (t-0.12)/0.33; cR = Math.floor(lerp(140,40,mt)); cG = Math.min(255, Math.floor(lerp(190,110,mt)) + Math.floor(s2*8)); cB = Math.min(255, Math.floor(lerp(255,220,mt)) + Math.floor(s1*6)); cA = Math.floor(lerp(200,150,mt)); }
            else { var mt2 = (t-0.45)/0.55; cR = Math.floor(lerp(40,15,mt2)); cG = Math.floor(lerp(110,50,mt2)); cB = Math.floor(lerp(220,110,mt2)); cA = Math.floor(lerp(150,20,mt2*mt2)); }
            break;
          default:
            cR = Math.floor(lerp(50,15,t)); cG = Math.floor(lerp(100,40,t));
            cB = Math.floor(lerp(180,80,t)); cA = Math.floor(lerp(120,15,t*t));
            break;
        }
        RectRGBA(slX, slY, tw, slH2, cR, cG, cB, cA);
      }
    }

    // Hot core
    for (var c = 0; c < 4; c++) {
      var ct = c / 3;
      var cs1 = Math.sin(tk * 0.5 + c * 1.3 + seed);
      var coreY = exhaTop + basePlumeH * ct * 0.5 + 1 + driftY * ct * ct;
      var coreX = schX + driftX * ct * ct + cs1 * 0.3;
      var coreW = nozzExitW * 0.15 * (1 - ct * 0.6);
      var coreH = basePlumeH * 0.15;
      var coreA = Math.floor(180 * (1 - ct));
      if (flameStage === 2) RectRGBA(coreX, coreY, coreW, coreH, 255, 240, 180, coreA);
      else if (flameStage === 1) RectRGBA(coreX, coreY, coreW, coreH, 200, 230, 255, coreA);
      else RectRGBA(coreX, coreY, coreW, coreH, 100, 150, 220, Math.floor(coreA * 0.5));
    }

    // Nozzle glow
    var glowPulse = Math.sin(tk * 0.37 + seed) * 0.1;
    var glowSize = nozzExitW * (1.0 + glowPulse);
    if (flameStage === 2) RectRGBA(schX, exhaTop + 1, glowSize, 2.5, 200, 150, 40, 110);
    else if (flameStage === 1) RectRGBA(schX, exhaTop + 1, glowSize, 2.5, 120, 170, 230, 90);
    else RectRGBA(schX, exhaTop + 1, glowSize, 2.5, 50, 90, 160, 50);
  }

  // Thrust bar
  var barY = y + availH - 14, barH3 = 3;
  Rect(x + w / 2, barY + barH3 / 2, w, barH3, T.BAR_TRACK);
  DrawRectangleOutline(x, barY, w, barH3, 0.5, T.BORDER);
  var fillW = w * thrustPct;
  if (fillW > 0.5) Rect(x + fillW / 2, barY + barH3 / 2, fillW, barH3, T.BAR_FILL);
  Txt(totalMax > 0 ? Math.floor(totalCur) + '/' + Math.floor(totalMax) + 'kN' : '---', x + w, barY + barH3 + 1, 0.28, T.STATUS_VAL, 'right');
}

// ═══════════════════════════════════════════════════════════════
function DrawPropulsionCard(x, y, w, h, thr, ab, tk, velocity) {
  Rect(x + w / 2, y + h / 2, w, h, T.PANEL_BG);
  DrawRectangleOutline(x, y, w, h, 1, T.BORDER_LIGHT);
  Txt("PROPULSION", x + w / 2, y + 2, 0.32, T.DIM_TEXT, 'center');
  var colW = (w - 14) / 2, colTop = y + 14, colH = h - 18;
  DrawEngineCol(x + 4, colTop, colW, colH, "ENG L", thr, ab, tk, velocity);
  DrawEngineCol(x + w - colW - 4, colTop, colW, colH, "ENG R", thr, ab, tk, velocity);
}

function DrawResourceCard(x, y, w, h, title, pct, timeStr) {
  Rect(x + w / 2, y + h / 2, w, h, T.PANEL_BG);
  DrawRectangleOutline(x, y, w, h, 1, T.BORDER_LIGHT);
  Txt(title, x + 4, y + 2, 0.32, T.DIM_TEXT_MID, 'left');
  Txt(Math.floor(pct * 100) + '%', x + w - 4, y + 1, 0.38, T.STATUS_VAL, 'right');
  var barY = y + 14, barW = w - 8, barH = 4, barX = x + 4;
  Rect(barX + barW / 2, barY + barH / 2, barW, barH, T.BAR_TRACK);
  DrawRectangleOutline(barX, barY, barW, barH, 0.5, T.BORDER);
  var fillW = barW * clamp(pct, 0, 1);
  if (fillW > 0.5) Rect(barX + fillW / 2, barY + barH / 2, fillW, barH, T.BAR_FILL);
  Txt("REMAIN", barX, barY + barH + 2, 0.28, T.DIM_TEXT, 'left');
  Txt(timeStr, barX + barW, barY + barH + 2, 0.28, T.STATUS_VAL, 'right');
}

// ═══════════════════════════════════════════════════════════════
// Throttle simulation + main loop
// ═══════════════════════════════════════════════════════════════
var PHASE_DURATIONS = [240, 120, 60, 180, 120, 180];

function updateThrottle() {
  phaseTick++;
  if (phaseTick > PHASE_DURATIONS[phase]) { phaseTick = 0; phase = (phase + 1) % 6; }
  var t = phaseTick / PHASE_DURATIONS[phase];
  switch (phase) {
    case 0: thrControl = lerp(0, 0.8, t); break;
    case 1: thrControl = 0.8; break;
    case 2: thrControl = lerp(0.8, 1.0, t); break;
    case 3: thrControl = 1.0; break;
    case 4: thrControl = lerp(1.0, 0, t); break;
    case 5: thrControl = 0; break;
  }
  abActive = thrControl > 0.8;
  if (abActive) { if (!lastAbState) abActiveTicks = 0; abActiveTicks++; } else { abActiveTicks = 0; }
  lastAbState = abActive;
  smoothedVel = smoothedVel * 0.95 + thrControl * 100 * 0.05;
}

function draw() {
  // Hide previous frame's elements
  for (var i = 0; i < prevRIdx; i++) rPool[i].style.display = 'none';
  for (var i = 0; i < prevTIdx; i++) tPool[i].style.display = 'none';
  rIdx = 0; tIdx = 0;

  tick++;
  updateThrottle();
  var abVisual = abActive && abActiveTicks > 2;

  var x = AREA.x, w = AREA.w, y = AREA.y, areaH = AREA.h, gap = 6, resH = 36;
  var propH = (areaH - 2 * (resH + gap)) * 0.75;
  if (propH < 50) propH = 50;

  DrawPropulsionCard(x, y, w, propH, thrControl, abVisual, tick, smoothedVel);
  y += propH + gap;

  var fuelPct = 0.72 - (tick % 6000) / 60000;
  var fuelSec = fuelPct * 600;
  var fm = Math.floor(fuelSec / 60), fs = Math.floor(fuelSec % 60);
  DrawResourceCard(x, y, w, resH, "H2 FUEL", fuelPct,
    (fm < 10 ? '0' : '') + fm + ':' + (fs < 10 ? '0' : '') + fs);
  y += resH + gap;
  DrawResourceCard(x, y, w, resH, "BATTERY", 0.85, "02:34");

  prevRIdx = rIdx; prevTIdx = tIdx;
  window.requestAnimationFrame(draw);
}

window.requestAnimationFrame(draw);
